#!/usr/bin/env python3
"""Generate skills/manifest.json, skills/SKILLS-INDEX.md and collections/README.md.

Usage: python scripts/build-collections.py [--root PATH] [--check]
--check performs no writes and exits 1 if any generated file is stale (used by CI).
"""
from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import skilllib as sl  # noqa: E402

HEADER = "<!-- Generated by scripts/build-collections.py. Do not edit by hand. -->\n"


def first_sentence(text: str, limit: int = 190) -> str:
    sentence = re.split(r"(?<=[.!?])\s", text.strip(), maxsplit=1)[0]
    return sentence if len(sentence) <= limit else sentence[: limit - 1].rstrip() + "…"


def build(root: Path) -> dict:
    skills = [s for s in sl.discover_skills(root) if not s.errors]
    collections = sl.load_collections(root)
    resolved = {}
    for name in collections:
        resolved[name] = sl.resolve_collection(name, collections)

    manifest = {
        "version": sl.read_version(root),
        "generated_by": "scripts/build-collections.py",
        "skills": [
            {
                "name": s.name,
                "category": s.category,
                "path": s.path.relative_to(root).as_posix(),
                "description": s.description,
                "version": s.version,
                "related": s.related,
                "files": [p.relative_to(s.path).as_posix() for p in sl.iter_files(s.path)],
            }
            for s in skills
        ],
        "collections": [
            {
                "name": n,
                "description": collections[n]["description"],
                "when_to_use": collections[n]["when_to_use"],
                "skills": resolved[n],
            }
            for n in sorted(collections)
        ],
    }

    by_cat: dict[str, list] = {}
    for s in skills:
        by_cat.setdefault(s.category, []).append(s)
    idx = [HEADER, "# Skills index\n",
           f"{len(skills)} skills in {len(by_cat)} categories. Install any of them with "
           "`python scripts/install-skills.py --skill NAME --target project` (see [installation](../docs/installation.md)).\n"]
    for cat in sorted(by_cat):
        idx.append(f"\n## {cat}\n\n| Skill | Use it for | Related |\n| --- | --- | --- |")
        for s in by_cat[cat]:
            rel = ", ".join(s.related) if s.related else "-"
            idx.append(f"| [{s.name}]({cat}/{s.name}/SKILL.md) | {first_sentence(s.description).replace('|', '/')} | {rel} |")
    idx.append("\n## Collections\n\n| Collection | Skills | When to use |\n| --- | --- | --- |")
    for n in sorted(collections):
        idx.append(f"| [{n}](../collections/README.md#{n}) | {len(resolved[n])} | {collections[n]['when_to_use']} |")
    index_md = "\n".join(idx) + "\n"

    cm = [HEADER, "# Collections\n",
          "A collection is a curated list of skills for one kind of work. Install one with "
          "`python scripts/install-skills.py --collection NAME --target project`. "
          "Skills load progressively in supporting agents: only names and descriptions are read at startup, "
          "so a collection costs little until a task matches a skill.\n"]
    skill_cat = {s.name: s.category for s in skills}
    for n in sorted(collections):
        data = collections[n]
        cm.append(f"\n## {n}\n\n{data['description']}\n\n**Use when:** {data['when_to_use']}\n")
        if data.get("includes"):
            cm.append("**Includes collections:** " + ", ".join(f"`{i}`" for i in data["includes"]) + "\n")
        cm.append(f"**{len(resolved[n])} skills:**\n")
        for s in resolved[n]:
            cat = skill_cat.get(s, "?")
            cm.append(f"- [{s}](../skills/{cat}/{s}/SKILL.md)")
    collections_md = "\n".join(cm) + "\n"

    return {
        "skills/manifest.json": json.dumps(manifest, indent=2, ensure_ascii=False) + "\n",
        "skills/SKILLS-INDEX.md": index_md,
        "collections/README.md": collections_md,
    }


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--root", default=str(sl.REPO_ROOT))
    ap.add_argument("--check", action="store_true", help="do not write; fail if generated files are stale")
    args = ap.parse_args(argv)
    root = Path(args.root).resolve()
    try:
        outputs = build(root)
    except sl.CollectionError as exc:
        print(f"build-collections: {exc}", file=sys.stderr)
        return 1
    stale = []
    for rel, content in outputs.items():
        path = root / rel
        current = path.read_text(encoding="utf-8") if path.exists() else None
        if current != content:
            stale.append(rel)
            if not args.check:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding="utf-8")
    if args.check:
        if stale:
            print("build-collections: stale generated files: " + ", ".join(stale))
            print("Run: python scripts/build-collections.py")
            return 1
        print("build-collections: generated files are up to date")
        return 0
    print("build-collections: wrote " + (", ".join(stale) if stale else "nothing (already up to date)"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
